const tabId = 2052873183;
const checkUrls = [
  "https://www.footlocker.com/product/nike-kobe-xi-em-protro-mens/U4902900.html",
  "https://www.footlocker.com/product/nike-kobe-iv-protro-mens/IV658590.html",
  "https://www.footlocker.com/product/nike-kobe-ix-em-protro-mens/H1401100.html",
  "https://www.footlocker.com/product/nike-kobe-air-force-1-low-mens/B0018102.html"
];

for (const u of checkUrls) {
  await tool.navigate({ tabId, url: u });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });
  const prod = await browserjs(tabId, () => {
    const title = document.querySelector('h1')?.innerText?.trim() || document.title;
    const price = document.querySelector('[data-test="product-price"], .ProductPrice')?.innerText?.trim() || '';
    const sizes = Array.from(document.querySelectorAll('[data-test="size-selector"] button, .c-form-field--radio, .ProductSize button'))
      .map(b => b.innerText.trim()).filter(Boolean);
    const addToCart = Array.from(document.querySelectorAll('button'))
      .map(b => b.innerText.trim())
      .filter(t => /add to cart|sold out|out of stock|unavailable/i.test(t));
    const isSoldOut = document.body.innerText.includes("Out of Stock") || document.body.innerText.includes("Sold Out");
    return { title, price, sizesCount: sizes.length, sizes: sizes.slice(0, 10), addToCart, isSoldOut, url: location.href };
  });
  console.log(JSON.stringify(prod));
}

